// Every real Northwind component renders data-nw-component="…".
// Some teams copied the nw-button class into their own components.
function measureAdoption(root) {
  const buttons = [...root.querySelectorAll('button')];
  const total = buttons.length;
  const system = buttons.filter((b) => b.dataset.nwComponent === 'Button').length;
  const percent = total === 0 ? 0 : Math.round((system / total) * 100);
  return { total, system, percent };
}

const result = measureAdoption(document);
document.querySelector('#report').textContent =
  `${result.system} of ${result.total} buttons use Northwind UI (${result.percent}%)`;
